import{_ as t,c as a,o as s,a3 as n}from"./chunks/framework.BNw1pucY.js";const i="/docs/architecture.svg",u=JSON.parse('{"title":"Agent SDK","description":"Build, test, and deploy bots and agents as code with the Agent SDK.","frontmatter":{"title":"Agent SDK","description":"Build, test, and deploy bots and agents as code with the Agent SDK."},"headers":[],"relativePath":"index.md","filePath":"README.md"}'),o={name:"index.md"};function r(d,e,l,p,h,c){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="agent-sdk" tabindex="-1">Agent SDK <a class="header-anchor" href="#agent-sdk" aria-label="Permalink to &quot;Agent SDK&quot;">​</a></h1><p>Agent SDK lets you define, test, evaluate, and deploy agents as code. It uses the Cursor SDK harness that powers Bugbot, Security Review, Approval Bot, and Rollouts.</p><p>An Agent&#39;s behavior is defined in a folder of Markdown and TypeScript that combines deterministic code with model judgment. Agent SDK makes it easy to build useful agents, with APIs to interact on Slack, pull requests, issue trackers, Cursor, and the other places where you get work done.</p><p>After you deploy an agent, open <a href="https://cursor.com/dashboard/deployed-agents" target="_blank" rel="noreferrer">Deployed Agents</a> to manage it.</p><h2 id="get-started-with-your-coding-agent" tabindex="-1">Get Started with your Coding Agent <a class="header-anchor" href="#get-started-with-your-coding-agent" aria-label="Permalink to &quot;Get Started with your Coding Agent&quot;">​</a></h2><p>Paste this prompt into your coding agent. It installs the CLI, asks what your agent is for, and scaffolds a first project from the Markdown version of these docs.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set up my first Agent SDK project.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Read https://cursor.com/docs/agent-sdk.md first. Every page under</span></span>
<span class="line"><span>https://cursor.com/docs/agent-sdk/ is also available as Markdown when you</span></span>
<span class="line"><span>add .md to its URL.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Check that Node is 22.13 or newer, then run:</span></span>
<span class="line"><span>   npm install --global @grok/agent-sdk</span></span>
<span class="line"><span>2. Read the docs index that ships with the package:</span></span>
<span class="line"><span>   &quot;$(npm root -g)/@grok/agent-sdk/dist/docs/llms.txt&quot;</span></span>
<span class="line"><span>3. Run agent-sdk login, and wait while I finish the browser sign-in.</span></span>
<span class="line"><span>4. Ask me what the agent should do and where people will reach it. Then</span></span>
<span class="line"><span>   follow the bdk-create-agent skill at</span></span>
<span class="line"><span>   &quot;$(npm root -g)/@grok/agent-sdk/skills/create-agent/SKILL.md&quot;</span></span>
<span class="line"><span>   to scaffold the project with agent-sdk init.</span></span>
<span class="line"><span>5. Run agent-sdk validate --dir . and one agent-sdk run turn, then show me</span></span>
<span class="line"><span>   the reply.</span></span></code></pre></div><h2 id="why-agent-sdk" tabindex="-1">Why Agent SDK <a class="header-anchor" href="#why-agent-sdk" aria-label="Permalink to &quot;Why Agent SDK&quot;">​</a></h2><p>Your instructions, tools, and evals are files you review, test, and version like the rest of your code. You write the instructions and tools, and Cursor runs the model loop that calls them.</p><h2 id="when-to-use-agent-sdk" tabindex="-1">When to use Agent SDK <a class="header-anchor" href="#when-to-use-agent-sdk" aria-label="Permalink to &quot;When to use Agent SDK&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Cursor Automations</th><th>Grok Bot</th><th>Agent SDK</th></tr></thead><tbody><tr><td><strong>You define</strong></td><td>A prompt, model, and trigger in the dashboard</td><td>Instructions, skills, and connected tools in the app</td><td>A versioned Markdown and TypeScript project</td></tr><tr><td><strong>Where it runs</strong></td><td>Cursor-managed</td><td>Cursor-managed</td><td>Cursor-managed hosting or your infrastructure</td></tr><tr><td><strong>Choose it when</strong></td><td>The job fits a schedule or event trigger</td><td>You want to configure and talk to an agent without writing code</td><td>You want code around model judgment that your team can version control, review, test and hillclimb</td></tr></tbody></table><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><p>Install <code>@grok/agent-sdk</code>, then scaffold and run a project. The package was <code>@cursor/bdk</code> before.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @grok/agent-sdk</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-bot</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-bot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent-sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><a href="./reference/project-layout.html">Project layout</a> explains every folder under <code>bot/</code>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./quickstart.html">Build your first PR reviewer agent</a> step by step.</li><li>Start from a <a href="./templates/reviews.html">review or triage template</a> or the <a href="./templates/agentic-owners.html">owners-policy approver</a>.</li><li><a href="./guides/convert-automation.html">Convert a Cursor Automation</a> into an Agent SDK project.</li><li><a href="./building-with-agents.html">Build agents with agents</a> using a coding agent.</li><li>Look up commands in the <a href="./reference/cli.html">CLI reference</a> and deployed-agent roles in <a href="./reference/access.html">Access</a>.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p><img src="`+i+'" alt="Agent SDK architecture"></p>',19)])])}const k=t(o,[["render",r]]);export{u as __pageData,k as default};
